import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { frontmatterText, quotedScalar } from '../../.cratis/ai/harnesses/pi/extensions/shared/frontmatter.ts';

/** Identifies adapters generated by setup, including stale outputs. */
export const copilotMarker = '<!-- cratis-ai: generated Copilot instructions.';
const marker = `${copilotMarker} Do not edit; rules/ is the source. -->`;

/** One Copilot instruction adapter; unchanged path rules link directly to their canonical source. */
export interface CopilotInstruction {
    path: string;
    target?: string;
    content?: string;
}

/** Plan repository-wide instructions and discoverable path rules without duplicating universal rules. */
export function copilotInstructions(corpus: string): CopilotInstruction[] {
    const instructions: CopilotInstruction[] = [];
    const universal: string[] = [];
    for (const name of readdirSync(join(corpus, 'rules')).filter(name => name.endsWith('.md')).sort()) {
        const content = readFileSync(join(corpus, 'rules', name), 'utf8');
        const fields = frontmatterText(content);
        const match = fields === undefined ? null : /^applyTo:([^\n]*)(?:\n[ \t]+[^\n]*)*/m.exec(fields);
        if (!match) {
            universal.push(content);
            continue;
        }
        const path = `.github/instructions/${name.slice(0, -3)}.instructions.md`;
        const raw = match[1].trim();
        const quoted = quotedScalar(raw);
        if (quoted !== undefined && quoted.trim() !== '') {
            instructions.push({ path, target: `../../.cratis/ai/rules/${name}` });
            continue;
        }
        // The corpus currently uses quoted strings already. Only normalize the simple scalar/list
        // forms if a future rule needs it; unsupported YAML must not silently broaden the scope.
        const globs = raw === ''
            ? match[0].split('\n').slice(1).map(line => /^\s+-\s+(.+)$/.exec(line)?.[1]).map(value => value && (quotedScalar(value) ?? value))
            : [raw];
        if (globs.length === 0 || globs.some(value => !value || /^[\[\]{|>]/.test(value) || value.includes(' #'))) {
            throw new Error(`rules/${name}: applyTo must be a glob string or a list of glob strings.`);
        }
        const normalized = `applyTo: ${JSON.stringify(globs.join(','))}\n`;
        const transformed = content.replace(match[0], normalized.trimEnd());
        const end = transformed.indexOf('\n---\n', 4) + 5;
        instructions.push({ path, content: `${transformed.slice(0, end)}${marker}\n${transformed.slice(end)}` });
    }
    instructions.push({ path: '.github/copilot-instructions.md', content: `${marker}\n\n${universal.join('\n\n')}` });
    return instructions;
}
